\label{thm:main}
Let $\mathcal{A}$ be a hyperplane arrangement. If $h_m(\mathcal{A})$ denotes the number of $m$-dimensional components of the resonance of $\mathcal{A}$, then for  $q\geq \mathrm{max}\{2, |\mathcal{A}|-1\}$, one has 
$$\theta_q\bigl(G(\mathcal{A})\bigr)=\sum_{m\geq 2} h_m(\mathcal{A}) \cdot \theta_q(F_m)=\sum_{m\geq 2} h_m(\mathcal{A})\cdot (q-1)\binom{m+q-2}{q}.$$

\label{lem:local-wedge}
Let $a,b\in V^{\vee}$ and $X\in L_2(\mathcal{A})$. Then
\begin{equation}
\label{eq:wedge-criterion}
a_X\wedge b_X\in I^2(\mathcal{A}_X)
\iff
(\partial_X a)\, b_X=(\partial_X b)\, a_X.
\end{equation}
In particular:
\begin{enumerate}[label=\textup{(\roman*)},itemsep=2pt]
\item \label{lw1} 
If $\partial_X a\ne 0$, then $a_X\wedge b_X\in I^2(\mathcal{A}_X)$ if and only
if $b_X$ is proportional to $a_X$.
\item \label{lw2}
If $a_X\ne 0$ and $\partial_X a=0$, then
$a_X\wedge b_X\in I^2(\mathcal{A}_X)$ if and only if $\partial_X b=0$.
\end{enumerate}

\label{def:multinet}
Let $\mathcal{B}\subseteq \mathcal{A}$ be a subarrangement. A \emph{$k$-multinet}
$\mathcal{N}=(\mathcal{B}_1,\dots,\mathcal{B}_k;m;\mathcal{X})$ on $\mathcal{B}$, with $k\ge 3$, consists of a partition
$\mathcal{B}=\mathcal{B}_1\sqcup \cdots \sqcup \mathcal{B}_k$, an assignment $m\colon \mathcal{B}\rightarrow \mathbb Z_{>0}$, and a
subset $\mathcal{X}\subseteq L_2(\mathcal{B})$, called the \emph{base locus} of the multinet, such that:
\begin{enumerate}[itemsep=2pt]
\item \label{m1} There is an integer $d>0$ with $\sum_{H\in \mathcal{B}_i}m_H=d$, for
$i=1,\dots,k$.
\item \label{m2} If $H\in \mathcal{B}_i$ and $L\in \mathcal{B}_j$ with $i\ne j$, then $H\cap L\in \mathcal{X}$.
\item \label{m3} For each $X\in \mathcal{X}$, the integer
$n_X\coloneqq \sum_{H\in \mathcal{B}_i,\, X\subseteq H} m_H$ does not depend on $i$.
\item \label{m4} For $i=1, \ldots, k$, the graph $\Gamma_i$ having vertex set $\mathcal{B}_i$ and an edge
$\{H,L\}$ whenever $H\cap L\notin \mathcal{X}$ is connected.
\end{enumerate}

\vskip 5pt

The integer $d$ is the \emph{weighted degree} of $\mathcal{N}$. Set
$u_i\coloneqq \sum_{H\in \mathcal{B}_i}m_H\cdot e_H\in V^{\vee}$ and
\begin{equation}
\label{eq:PN}
P_{\mathcal{N}}\coloneqq \Bigl\{\sum_{i=1}^k \lambda_i u_i : \sum_{i=1}^k \lambda_i=0\Bigr\}
=\operatorname{span}\{u_2-u_1,\dots,u_k-u_1\}\subseteq V^{\vee} .
\end{equation}
The vectors $u_i$ are linearly independent, and therefore $\dim P_{\mathcal{N}}=k-1\ge 2$.

\label{thm:factorization}
Let $\mathcal{N}$ be a multinet on a subarrangement $\mathcal{B}\subseteq \mathcal{A}$ and set $P=P_{\mathcal{N}}$. Then
\begin{equation}
\label{eq:factorization}
\bigl(P\wedge V^{\vee}\bigr)\cap I^2(\mathcal{A})=P\wedge \operatorname{Cent}_{\mathcal{A}}(P).
\end{equation}

\label{prop:cent-local}

Let $P=P_{\mathcal{N}}$ be as above and $g\in V^{\vee}$. Then $g\in \operatorname{Cent}_{\mathcal{A}}(P)$ if and only~if:
\begin{enumerate}[label=\textup{(C\arabic*)},itemsep=2pt]
\item \label{C1} $\partial_X g=0$, for every $X\in \mathcal{X}$, and
\item \label{C2} for every block $\mathcal{B}_i$ and every $Y\in L_2(\mathcal{A})\setminus \mathcal{X}$ meeting $\mathcal{B}_i$, $g_Y$ is proportional to $(u_i)_Y$.
\end{enumerate}

\label{lem:outside}
Fix a block index $i$ and assume that $g\in V^{\vee}$ is such that $g_Y$ is proportional to
$(u_i)_Y$ for every $Y\in L_2(\mathcal{A})\setminus \mathcal{X}$ meeting $\mathcal{B}_i$. If $H\in \mathcal{A}\setminus
\mathcal{B}$ satisfies $g_H\ne 0$, then
\begin{equation}
\label{eq:allbase}
H\cap L\in \mathcal{X} \qquad \text{for every } L\in \mathcal{B}.
\end{equation}

\label{lem:blockwise}
Let $g\in V^{\vee}$ such that $\partial g=0$ and $\partial_X g=0$ for all $X\in \mathcal{X}$. We
assume that every $H\in \mathcal{A}\setminus \mathcal{B}$ with $g_H\ne 0$ satisfies \eqref{eq:allbase}.
Then for each $j$ there is a scalar $c_j$ with
\begin{equation}
\label{eq:proportional}
g_H=c_j\, m_H, \qquad \text{ for all }H\in \mathcal{B}_j.
\end{equation}

\label{prop:propagation}
Fix a block index $i$ and assume that an element $g\in V^{\vee}$ satisfies:
\begin{enumerate}[label=\textup{(P\arabic*)},itemsep=2pt]
\item \label{P1} $\partial g=0$;
\item \label{P2} $\partial_X g=0$, for every $X\in \mathcal{X}$;
\item \label{P3} $g_Y$ is proportional to $(u_i)_Y$ for every
$Y\in L_2(\mathcal{A})\setminus \mathcal{X}$ meeting $\mathcal{B}_i$.
\end{enumerate}
Then $g\in \operatorname{Cent}_{\mathcal{A}}(P_{\mathcal{N}})$.

\label{cor:separable-maximal}
If $\mathcal{N}$ is a multinet on a subarrangement $\mathcal{B}\subseteq \mathcal{A}$ such that $P_{\mathcal{N}}$ is maximal among
the isotropic subspaces of $V^{\vee}$, then $P_{\mathcal{N}}$ is separable.
